(function(){
 const M=SurveyModel,KEY='viewdding.album.survey.v1',DRAFT=KEY+'.draft';
 let answers={},step=0,mode='self',pair=null,view='form',lastRoute=null,region='seoul',storageOK=true,invalidLink=false;
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const read=key=>{try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
 function write(key,value){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,JSON.stringify(value));return true}catch{storageOK=false;return false}}
 const steps=()=>mode==='partner'?M.steps.filter(s=>s.part.mode==='individual'):M.steps;
 const current=()=>steps()[step];
 const get=id=>answers[id]||[];
 const picked=(id,v)=>get(id).includes(v);
 function saveDraft(){write(DRAFT,{answers,step,mode,basePair:pair})}
 function init(){
  const route=location.hash;if(lastRoute===route)return;lastRoute=route;invalidLink=false;
  const params=new URLSearchParams(route.split('?')[1]||'');
  if(params.has('p')||params.has('code')){
   pair=M.decode(params.get('p')||params.get('code'));if(!pair){invalidLink=true;return}
   if(params.has('p')){mode='partner';answers=Object.fromEntries(Object.entries(pair.primary.answers).filter(([k])=>k.startsWith('A')));step=0;view='form'}
   else{view='report';write(KEY,pair)}return;
  }
  const draft=read(DRAFT),saved=M.cleanPair(read(KEY));pair=saved;
  if(draft&&M.cleanAnswers(draft.answers)&&['self','partner'].includes(draft.mode)){
   const base=M.cleanPair(draft.basePair);if(draft.mode==='partner'&&!base){view=saved?'report':'form';return}
   answers=M.cleanAnswers(draft.answers);mode=draft.mode;pair=base||saved;step=Math.max(0,Math.min(Number.isInteger(draft.step)?draft.step:0,steps().length-1));
   const firstInvalid=steps().findIndex(s=>!M.valid(s.question,answers));if(firstInvalid>=0)step=Math.min(step,firstInvalid);view='form';
  }else{answers={};step=0;mode='self';view=pair?'report':'form'}
 }
 const tabs=()=>'';
 function choice(id,option,kind='single',rank=0){const active=picked(id,option.value);return `<button type="button" id="survey-${e(id)}-${e(option.value)}" class="survey-choice ${active?'is-selected':''}" data-survey-choice="${e(id)}" data-value="${e(option.value)}" data-kind="${kind}" aria-pressed="${active}"><span class="survey-choice-mark ${kind==='multi'?'is-multi':''}" aria-hidden="true">${active?(rank||'✓'):''}</span><span><strong>${e(option.label)}</strong>${option.sublabel?`<small>${e(option.sublabel)}</small>`:''}</span></button>`}
 const options=(q)=>`<div class="survey-options">${q.options.map(o=>choice(q.id,o,['multi','photo-card','pick-n'].includes(q.type)?'multi':'single',q.type==='pick-n'?get(q.id).indexOf(o.value)+1:0)).join('')}</div>`;
 const choices=(id,opts,multi=false)=>`<div class="survey-options">${opts.map(o=>choice(id,o,multi?'multi':'single')).join('')}</div>`;
 function field(id,label,type='number',unit='',attributes=''){return `<label class="survey-input-label" for="survey-input-${id}">${label}<span class="survey-input-wrap"><input id="survey-input-${id}" data-survey-input="${id}" type="${type}" value="${e(M.first(answers,id)===''?'':id==='A4-max'?Number(M.first(answers,id))/10000:M.first(answers,id))}" ${attributes}>${unit?`<span>${unit}</span>`:''}</span></label>`}
 function regionPicker(){const group=HallRegions.groups.find(g=>g.id===region)||HallRegions.groups[1];return `<div class="survey-region"><div class="survey-region-groups" data-survey-scroll="region-groups" aria-label="시·도">${HallRegions.groups.map(g=>`<button type="button" id="survey-region-${g.id}" data-survey-region="${g.id}" aria-pressed="${g.id===group.id}" class="${g.id===group.id?'is-selected':''}">${e(g.name)}</button>`).join('')}</div><div class="survey-region-bundles" data-survey-scroll="bundles-${group.id}" aria-label="${e(group.name)} 세부 지역">${group.bundles.map(b=>choice('A1',{value:b.id,label:b.label},'multi')).join('')}</div></div><div class="survey-region-selected"><p>선택한 지역 <strong>${get('A1').length}곳</strong></p>${get('A1').length?`<div class="survey-chips">${get('A1').map(id=>`<button type="button" data-survey-choice="A1" data-value="${e(id)}" aria-label="${e(HallModel.bundles.find(b=>b.id===id)?.label)} 선택 해제">${e(HallModel.bundles.find(b=>b.id===id)?.label)} <span aria-hidden="true">×</span></button>`).join('')}</div>`:'<span>오른쪽에서 고려할 지역을 골라주세요.</span>'}</div>`}
 function budgetCard(a){const b=M.budget(a);return `<section class="survey-budget-reference" aria-label="식장 비용 참고 계산"><div class="survey-budget-heading"><span>${e(b.name)} 공개 중간값 기준</span><strong>${M.money(b.total)}<small>부터</small></strong><span>${b.guests===null?'하객 수 미정 · ':''}${b.billable}명 ${b.guests===null?'예시':'청구 기준'}</span></div><dl><div><dt>식대 <span>${M.money(b.meal)} × ${b.billable}명</span></dt><dd>${M.money(b.subtotal)}</dd></div><div><dt>대관료</dt><dd>${M.money(b.rental)}</dd></div></dl>${b.guests!==null&&b.guests<b.minimum?`<p>예상 하객은 ${b.guests}명이지만, 참고 통계의 최소보증 ${b.minimum}명으로 식대를 계산했어요.</p>`:''}<p class="survey-help">뷰딩 서베이 참고값 · 확인일 ${b.checkedAt}. 장식·음료·세금·필수 옵션은 별도일 수 있어요. 실제 견적은 상담에서 확인해주세요.</p><a href="${b.source}" target="_blank" rel="noopener noreferrer">통계 출처 · 한국소비자원 참가격 ↗</a></section>`}
 function questionBody(q){
  if(q.type==='region-picker')return regionPicker();
  if(q.type==='schedule'){
   const p=M.first(answers,'A2-precision');return `<fieldset><legend>희망 시기</legend>${choices('A2-precision',q.precisionOptions)}${p==='exact_date'?field('A2-date','희망 날짜','date'):p==='year_month'?field('A2-month','희망 월','month'):p==='season'?`<div class="survey-subfield">${choices('A2-season',q.seasonOptions)}</div>`:''}</fieldset>${p&&p!=='open'?`<fieldset><legend>시기를 얼마나 넓게 볼까요?</legend>${choices('A2-flexibility',q.flexibilityOptionsByPrecision[p])}</fieldset><fieldset><legend>선호 요일 <small>선택 · 복수 응답</small></legend>${choices('A2-weekdays',q.weekdayOptions,true)}</fieldset><fieldset><legend>선호 시간 <small>선택 · 복수 응답</small></legend>${choices('A2-times',q.timeOptions,true)}</fieldset>`:p==='open'?'<p class="survey-info">마음에 드는 웨딩홀의 일정에 맞춰 시기를 정하는 것으로 반영할게요.</p>':''}`;
  }
  if(q.type==='budget-builder')return budgetCard(answers)+`<fieldset><legend>이 참고 금액을 보고 예산 기준을 정해보세요.</legend>${choices('A4',q.strategyOptions)}${picked('A4','custom')?field('A4-max','식대와 대관료를 합친 최대 금액','number','만 원','inputmode="numeric" min="100" max="10000000" step="50"'):''}</fieldset>`;
  if(q.type==='group')return q.groupQuestions.map(sub=>`<fieldset><legend>${e(sub.question)}${sub.type==='multi'?'<small>복수 선택 가능</small>':''}</legend>${options(sub)}</fieldset>`).join('');
  if(q.type==='photo-card')return `<div class="survey-photo-options">${q.options.filter(o=>!o.exclusive).map(o=>`<button type="button" id="survey-B1-${o.value}" class="survey-photo-choice ${picked('B1',o.value)?'is-selected':''}" data-survey-choice="B1" data-value="${o.value}" aria-pressed="${picked('B1',o.value)}"><span class="survey-photo-wrap"><img src="${o.image}" alt="${e(o.label)} 분위기 예시" loading="lazy" width="1200" height="896"><span class="survey-photo-check" aria-hidden="true">${picked('B1',o.value)?'✓':'+'}</span></span><span class="survey-photo-caption"><strong>${e(o.label)}</strong><small>${e(o.sublabel)}</small></span></button>`).join('')}</div>${choice(q.id,q.options.find(o=>o.exclusive),'multi')}<p class="survey-help">공간 분위기를 고르기 위한 이미지예요. 특정 웨딩홀의 실제 모습과는 다를 수 있어요.</p>`;
  if(q.type==='pick-n')return `<ol class="survey-ranking" aria-label="선택한 우선순위">${[0,1,2].map(i=>`<li><span>${i+1}순위</span><strong>${get('B4')[i]?e(M.label('B4',get('B4')[i])):'선택해 주세요'}</strong></li>`).join('')}</ol>${options(q)}`;
  return options(q)+(q.type==='guest-estimate'&&get('A3').length&&!picked('A3','unknown')?field('A3-exact','더 정확한 예상 인원 <small>선택</small>','number','명','inputmode="numeric" min="1" max="2000" step="1"'):'');
 }
 function hint(){const q=current().question;if(M.valid(q,answers))return '선택을 마쳤어요. 다음으로 이어가세요.';return q.type==='pick-n'?`${get(q.id).length} / 3 선택 · 중요한 순서대로 골라주세요.`:q.type==='photo-card'?`${get(q.id).length} / 2 선택 가능`:q.type==='schedule'?'희망 시기와 조정 가능한 범위를 입력해주세요.':q.type==='budget-builder'&&picked('A4','custom')?'최대 금액을 100만 원 이상 입력해주세요.':q.type==='guest-estimate'&&get('A3').length?'예상 인원은 1~2,000명의 정수로 입력해주세요.':'답변을 선택하면 다음으로 갈 수 있어요.'}
 function form(){const all=steps(),{part,question:q}=current();return `<div class="survey-progress"><span>${mode==='partner'?'파트너 취향':'내 기준'} 작성</span><progress value="${step+1}" max="${all.length}" aria-label="${step+1} / ${all.length} 문항"></progress><strong>${step+1} <span>/ ${all.length}</span></strong><span>약 ${mode==='partner'?2:4}분</span></div><div class="survey-layout"><aside class="survey-rail"><p class="section-eyebrow">OUR WEDDING STANDARD</p><h2>우리에게 맞는<br>공간의 기준.</h2><ol>${all.map((s,i)=>`<li class="${i===step?'current':''}"><button type="button" data-survey-step="${i}" ${i>step&&!all.slice(0,i).every(x=>M.valid(x.question,answers))?'disabled':''} ${i===step?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${({A1:'고려 지역',A2:'희망 일정',A3:'하객 규모',A4:'식장 예산',A5:'교통과 접근',B1:'공간 분위기',B2:'예식 운영',B3:'하객 식사',B4:'우선순위'})[s.question.id]}${M.valid(s.question,answers)?'<i aria-label="답변 완료">✓</i>':''}</button></li>`).join('')}</ol><p class="survey-help">${storageOK?'작성 내용은 이 브라우저에 보관돼요.':'브라우저 저장이 제한되어 이번 방문 동안만 유지돼요.'}</p>${pair?'<button type="button" class="text-button" data-survey-action="report">저장한 리포트 보기 →</button>':''}</aside><section class="survey-question-card" aria-labelledby="survey-question-title"><header><p class="survey-question-meta">${e(part.title)} <span>${q.type==='pick-n'?'순서대로 3개':q.type==='photo-card'?'최대 2개 선택':q.type==='region-picker'?'복수 선택 가능':'질문 '+String(step+1).padStart(2,'0')}</span></p><h2 id="survey-question-title" tabindex="-1">${e(q.question)}</h2>${q.help?`<p class="survey-question-help">${e(q.help)}</p>`:''}</header><div class="survey-question-body">${questionBody(q)}</div><div class="survey-question-footer"><p id="survey-hint" role="status">${hint()}</p><div><button type="button" class="outline-button" data-survey-action="previous" ${step===0?'disabled':''}>← 이전</button><button type="button" class="solid-button" id="survey-next" data-survey-action="next" ${M.valid(q,answers)?'':'disabled'}>${step===all.length-1?'기준 리포트 보기':'다음 질문'} →</button></div></div></section></div>`}
 const moodCards=values=>{const opts=M.byId('B1').options.filter(o=>values.includes(o.value)&&o.image);return opts.length?`<div class="survey-report-moods">${opts.map(o=>`<figure><img src="${o.image}" alt="${e(o.label)} 분위기 예시" loading="lazy" width="1200" height="896"><figcaption>${e(o.label)}</figcaption></figure>`).join('')}</div>`:'<p class="survey-help">후보를 직접 둘러보며 분위기를 정해도 괜찮아요.</p>'};
 const priorityList=(values,details=true)=>`<ol class="survey-report-priorities">${values.map((v,i)=>`<li><span>${i+1}</span><div><strong>${e(M.label('B4',v))}</strong>${details?`<p>${e(M.commentary[v])}</p>`:''}</div></li>`).join('')}</ol>`;
 function report(){const a=pair.primary.answers,b=pair.partner?.answers,c=M.comparison(pair),estimate=M.budget(a),priorities=c?c.priorities:a.B4||[];
  const format=M.first(a,'B2-format'),solo=M.first(a,'B2-solo');
  return `<section class="survey-report-intro"><div><p class="section-eyebrow">${c?'OUR':'MY'} WEDDING STANDARD</p><h2 id="survey-report-title" tabindex="-1">${c?'함께 정하는, 우리의 기준.':'우리다운 웨딩홀을 위한 기준.'}</h2><p>${priorities.length?e(M.label('B4',priorities[0]))+'부터 살펴보고, 아래 기준으로 후보를 비교해보세요.':'서로의 우선순위를 보며 함께 지킬 기준부터 정해보세요.'}</p></div><div class="survey-report-actions"><button type="button" class="solid-button" data-survey-action="search">이 기준으로 웨딩홀 찾기 →</button><button type="button" class="text-button" data-survey-action="edit">내 응답 수정</button></div></section><div class="survey-report"><section class="survey-report-section"><div class="survey-section-title"><span>01</span><h2>함께 정할 기본 조건</h2></div><dl class="survey-summary">${M.summary(a).map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></section><section class="survey-report-section"><div class="survey-section-title"><span>02</span><h2>${c?'두 사람의 우선순위':'가장 중요한 세 가지'}</h2></div>${c?`<p class="survey-shared">함께 고른 기준 <strong>${c.priorities.length?c.priorities.map(v=>e(M.label('B4',v))).join(' · '):'아직 겹치는 기준이 없어요'}</strong></p><div class="survey-pair-columns"><div><h3>나의 우선순위</h3>${priorityList(a.B4,false)}</div><div><h3>파트너의 우선순위</h3>${priorityList(b.B4,false)}</div></div>`:priorityList(a.B4)}${c?.talking.length?`<div class="survey-conversation"><h3>함께 이야기해 볼 것</h3>${c.talking.map(t=>`<article><h4>${e(t.title)}</h4><p>${e(t.question)}</p><div><span>나 · ${e(t.self)}</span><span>파트너 · ${e(t.partner)}</span></div></article>`).join('')}</div>`:''}</section><section class="survey-report-section"><div class="survey-section-title"><span>03</span><h2>잘 맞는 공간과 예식 방식</h2></div>${c?`<h3>함께 고른 분위기</h3>${moodCards(c.moods)}<div class="survey-pair-columns"><div><h3>나만 고른 분위기</h3>${moodCards(c.selfMoods)}</div><div><h3>파트너만 고른 분위기</h3>${moodCards(c.partnerMoods)}</div></div>`:moodCards(a.B1||[])}<div class="survey-pair-columns survey-preferences"><div><h3>${c?'나의 예식 취향':'예식 취향'}</h3><p>${e(M.label('B2-format',format))}</p><p>${e(M.label('B2-solo',solo))}</p><p>식사 · ${e(M.label('B3',M.first(a,'B3')))}</p></div>${c?`<div><h3>파트너의 예식 취향</h3><p>${e(M.label('B2-format',M.first(b,'B2-format')))}</p><p>${e(M.label('B2-solo',M.first(b,'B2-solo')))}</p><p>식사 · ${e(M.label('B3',M.first(b,'B3')))}</p></div>`:''}</div></section><section class="survey-report-section"><div class="survey-section-title"><span>04</span><h2>후보를 볼 때 확인할 것</h2></div><div class="survey-pair-columns"><div><h3>끝까지 지킬 것</h3><ul>${(priorities.length?priorities.map(v=>M.label('B4',v)):['함께 지킬 우선순위부터 정하기']).map(v=>`<li>${e(v)}</li>`).join('')}</ul></div><div><h3>상담에서 확인할 것</h3><ul><li>희망 일정의 예약 가능 시간과 최소보증인원</li><li>장식·음료·세금·필수 옵션을 포함한 최종 견적</li>${getExtra(a,'parking_ease')?'<li>주차 가능 대수와 무료 주차 시간</li>':''}</ul></div></div><details><summary>후보가 적을 때 조정할 수 있는 조건</summary><p>${M.first(a,'A2-flexibility')==='nearby_period'?'선택한 시기의 앞뒤 기간까지 후보를 넓혀보세요.':['price_flexible','venue_first'].includes(M.first(a,'A2-flexibility'))?'가격이나 공간이 잘 맞는다면 다른 시기까지 비교해보세요.':'우선순위 세 가지 밖의 조건부터 조정 가능한지 이야기해보세요.'}</p></details></section><section class="survey-report-section"><div class="survey-section-title"><span>05</span><h2>식장 예산 기준</h2></div>${budgetCard(a)}<p class="survey-budget-target">우리의 기준 <strong>${e(M.budgetLabel(estimate))}</strong></p></section><section class="survey-report-section"><div class="survey-section-title"><span>06</span><h2>이제 함께 비교해 보세요</h2></div><div class="survey-tool-grid"><article><h3>${c?'파트너 응답 다시 작성':'파트너의 취향도 들어볼까요?'}</h3><p>기본 조건은 함께 쓰고, 파트너는 취향 4문항만 답해요.</p><button type="button" class="outline-button" data-survey-action="partner">이 기기에서 파트너 응답</button><button type="button" class="text-button" data-survey-action="invite">파트너 초대 링크 복사</button></article><article><h3>맞춤형 투어 체크리스트</h3><p>선택한 우선순위에 맞춰 현장에서 확인할 항목을 정리했어요.</p><button type="button" class="outline-button" data-survey-action="download">체크리스트 다운로드 ↓</button></article><article><h3>견적·상담 문의 템플릿</h3><p>일정·하객 수·예산을 담은 문의 내용을 준비했어요.</p><details><summary>문의 내용 미리보기</summary><pre>${e(M.template(pair))}</pre></details><button type="button" class="outline-button" data-survey-action="template">문의 내용 복사</button></article></div><p class="survey-help">초대·결과 링크에는 응답 내용이 포함됩니다. 현재 사이트에 접근 권한이 있는 파트너와 공유해주세요.</p><div class="survey-bottom-actions"><button type="button" class="text-button" data-survey-action="share">${c?'두 사람의 결과':'결과'} 링크 복사</button><button type="button" class="solid-button" data-survey-action="search">이 기준으로 웨딩홀 찾기 →</button></div><p class="survey-help">검색에는 지역·인원·분위기·예식 방식이 반영됩니다. 커플 결과는 공통 취향을 적용하며, 예산과 잔여 일정은 상담에서 확인해요.</p></section></div>`;
 }
 const getExtra=(a,v)=>(a['A5-extra']||[]).includes(v);
 function body(){return invalidLink?'<section class="empty-state"><h2>응답 링크를 확인할 수 없어요.</h2><p>링크가 잘렸거나 지원하지 않는 응답일 수 있어요.</p><a href="#survey" class="outline-button">내 서베이로 돌아가기</a></section>':view==='report'&&pair?report():form()}
 function renderPage(){init();return `${heading('','내 기준 서베이','9개 질문으로 조건과 취향을 정리하고, 두 사람에게 맞는 웨딩홀 기준을 세워보세요.')}${tabs('survey')}<div id="survey-explorer">${body()}</div>`}
 function repaint(move=false){const host=document.getElementById('survey-explorer');if(!host)return;const top=window.scrollY,left=window.scrollX,id=document.activeElement?.id;const scroll=[...host.querySelectorAll('[data-survey-scroll]')].map(el=>[el.dataset.surveyScroll,el.scrollTop,el.scrollLeft]);host.innerHTML=body();if(move){const title=document.getElementById(view==='report'?'survey-report-title':'survey-question-title');title?.focus({preventScroll:true});title?.scrollIntoView({block:'nearest',behavior:'instant'})}else{if(id)document.getElementById(id)?.focus({preventScroll:true});for(const [key,y,x]of scroll){const el=host.querySelector(`[data-survey-scroll="${key}"]`);if(el){el.scrollTop=y;el.scrollLeft=x}}window.scrollTo({top,left,behavior:'instant'})}}
 function status(){const button=document.getElementById('survey-next'),help=document.getElementById('survey-hint');if(button)button.disabled=!M.valid(current().question,answers);if(help)help.textContent=hint()}
 function set(id,value){answers[id]=value;saveDraft()}
 function clearLink(){history.replaceState(null,'',location.pathname+location.search+'#survey');lastRoute=location.hash}
 async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message)}catch{openDialog(`<h2>아래 내용을 복사해주세요</h2><textarea class="survey-copy-fallback" readonly aria-label="복사할 내용">${e(text)}</textarea>`);document.querySelector('.survey-copy-fallback')?.select()}}
 const link=kind=>location.origin+location.pathname+'#survey?'+kind+'='+M.encode(pair);
 document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-survey-choice],[data-survey-region],[data-survey-step],[data-survey-action]');if(!el||el.disabled)return;
  if(el.dataset.surveyRegion){region=el.dataset.surveyRegion;repaint();return}
  if(el.dataset.surveyStep!==undefined){const next=Number(el.dataset.surveyStep);if(next>=0&&next<steps().length&&(next<=step||steps().slice(0,next).every(s=>M.valid(s.question,answers)))){step=next;saveDraft();repaint(true)}return}
  const id=el.dataset.surveyChoice,value=el.dataset.value;
  if(id){
   if(id==='A1')set(id,HallModel.toggleBundle(get(id),value));
   else if(id==='A2-precision'){answers[id]=[value];for(const key of ['A2-flexibility','A2-date','A2-month','A2-season','A2-weekdays','A2-times'])answers[key]=[];if(value==='open')answers['A2-flexibility']=['venue_first'];saveDraft()}
   else if(['A2-weekdays','A2-times'].includes(id))set(id,picked(id,value)?get(id).filter(v=>v!==value):[...get(id),value]);
   else if(id.startsWith('A2-')||id==='A4'){set(id,[value]);if(id==='A4'&&value!=='custom')set('A4-max',[])}
   else{const q=M.byId(id);if(!q)return;const next=M.toggle(q,get(id),value);if(next===get(id)){toast(q.type==='pick-n'?'우선순위는 3개까지 선택할 수 있어요. 기존 선택을 해제해주세요.':'분위기는 2개까지 고를 수 있어요.');return}set(id,next);if(id==='A3'&&value==='unknown')set('A3-exact',[])}
   repaint();return;
  }
  switch(el.dataset.surveyAction){
   case 'previous':if(step>0){step--;saveDraft();repaint(true)}break;
   case 'next':if(!M.valid(current().question,answers))return;if(step<steps().length-1){step++;saveDraft();repaint(true)}else{
    if(!steps().every(s=>M.valid(s.question,answers)))return;
    const record={answers:mode==='partner'?Object.fromEntries(Object.entries(answers).filter(([k])=>k.startsWith('B'))):answers,completedAt:new Date().toISOString()};
    pair=mode==='partner'?{...pair,partner:record}:{version:M.schema.version,primary:record,...(pair?.partner?{partner:pair.partner}:{})};
    write(KEY,pair);write(DRAFT,null);view='report';clearLink();repaint(true);if(!storageOK)toast('브라우저 저장이 제한되어 있어요. 결과 링크를 복사해 보관해주세요.');
   }break;
   case 'edit':answers=JSON.parse(JSON.stringify(pair.primary.answers));mode='self';step=0;view='form';clearLink();saveDraft();repaint(true);break;
   case 'partner':answers=Object.fromEntries(Object.entries(pair.primary.answers).filter(([k])=>k.startsWith('A')));mode='partner';step=0;view='form';clearLink();saveDraft();repaint(true);break;
   case 'report':view='report';repaint(true);break;
   case 'search':VenueExplorer.applySurvey(M.filters(pair));location.hash='halls';break;
   case 'invite':await copy(link('p'),'파트너 초대 링크를 복사했어요.');break;
   case 'share':await copy(link('code'),'결과 링크를 복사했어요.');break;
   case 'template':await copy(M.template(pair),'상담 문의 내용을 복사했어요.');break;
   case 'download':{const blob=new Blob([M.csv(pair)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='뷰딩_웨딩홀_투어체크리스트.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);break}
  }
 });
 document.addEventListener('input',event=>{const el=event.target,id=el.dataset.surveyInput;if(!id)return;set(id,el.value===''?[]:[id==='A4-max'?String(Number(el.value)*10000):el.value]);status()});
 window.VenueSurvey={render:renderPage,tabs};
})();
